const input = $input.first().json;
const candidatePatch = input.candidate_patch || input.payload?.candidate_patch || input.body?.candidate_patch || null;
const operatorDecision = input.operator_decision || input.payload?.operator_decision || input.body?.operator_decision || {};
const decision = operatorDecision.decision || input.decision || input.payload?.decision || input.body?.decision || 'REQUEST_REVISION';
const comment = operatorDecision.comment || input.comment || input.payload?.comment || input.body?.comment || '';
const operatorId = input.operator_id || input.context?.operator_id || input.body?.operator_id || candidatePatch?.operator_id || 'operator_pending';

return [{
  json: {
    ...input,
    candidate_patch: candidatePatch,
    decision,
    comment,
    operator_id: operatorId,
    operator_decision: {
      decision,
      comment,
      raw_reply: operatorDecision.raw_reply || input.payload?.raw_release_decision_reply || null
    },
    context: input.context || {},
    payload: {
      ...(input.payload || {}),
      candidate_patch: candidatePatch,
      decision,
      comment,
      operator_decision: {
        decision,
        comment,
        raw_reply: operatorDecision.raw_reply || input.payload?.raw_release_decision_reply || null
      }
    },
    body: {
      candidate_patch: candidatePatch,
      decision,
      comment,
      operator_id: operatorId,
      operator_decision: {
        decision,
        comment,
        raw_reply: operatorDecision.raw_reply || input.payload?.raw_release_decision_reply || null
      }
    }
  }
}];

const input = $input.first().json;
const error = 'Release approval input is missing candidate_patch.';
return [{
  json: {
    status: 'NEEDS_REVISION',
    context: input.context || {},
    ids: {
      release_id: null,
      patch_id: input.context?.patch_id || null,
      audit_id: null,
      trt_id: input.context?.trt_id || null,
      trt_version: input.context?.trt_version || null,
      reconciliation_plan_id: input.context?.reconciliation_plan_id || null,
      scenario_spec_id: null
    },
    payload: {
      message: 'Release needs revision.',
      comment: error,
      decision: input.decision || 'REQUEST_REVISION'
    },
    errors: [error]
  }
}];

const input = $input.first().json;
const original = $('Normalize Release Approval Input').first().json;
const prepared = $('Prepare Pending Release').item.json;
const comment = input.operator_decision?.comment || original.comment || input.comment || 'Release rejected.';
return [{
  json: {
    status: input.status || 'REJECTED_BY_OPERATOR',
    context: {
      ...(original.context || {}),
      patch_id: prepared.patch_id || original.context?.patch_id || null,
      release_id: prepared.release_id,
      audit_id: input.audit_id || null,
      trt_id: original.context?.trt_id || original.candidate_patch?.trt_id || null,
      trt_version: original.context?.trt_version || original.candidate_patch?.base_version || null,
      reconciliation_plan_id: original.context?.reconciliation_plan_id || null,
      scenario_batch_id: original.context?.scenario_batch_id || null,
      scenario_spec_ids: original.context?.scenario_spec_ids || []
    },
    ids: {
      release_id: prepared.release_id,
      patch_id: prepared.patch_id || null,
      audit_id: input.audit_id || null,
      trt_id: null,
      trt_version: null,
      reconciliation_plan_id: null,
      scenario_spec_id: null
    },
    payload: {
      ...input,
      message: 'Release rejected.',
      comment
    },
    errors: [comment]
  }
}];

